export function getAuthenticTrackGeometry(trackNameOrHint: string, totalDist?: number): RealCircuitDefinition | null {
  const lower = (trackNameOrHint || "").toLowerCase();

  // Match by explicit keywords
  if (lower.includes("redbull") || lower.includes("red bull") || lower.includes("spielberg") || lower.includes("austria") || lower.includes("rbr")) {
    return REAL_CIRCUITS.redbullring;
  }
  if (lower.includes("spa") || lower.includes("francorchamps")) {
    return REAL_CIRCUITS.spa;
  }
  if (lower.includes("monza") || lower.includes("rettifilo")) {
    return REAL_CIRCUITS.monza;
  }
  if (lower.includes("silverstone")) {
    return REAL_CIRCUITS.silverstone;
  }
  if (lower.includes("suzuka")) {
    return REAL_CIRCUITS.suzuka;
  }
  if (lower.includes("interlagos") || lower.includes("pace") || lower.includes("sao paulo") || lower.includes("brasil")) {
    return REAL_CIRCUITS.interlagos;
  }
  if (lower.includes("cota") || lower.includes("americas") || lower.includes("austin")) {
    return REAL_CIRCUITS.cota;
  }
  if (lower.includes("zandvoort")) {
    return REAL_CIRCUITS.zandvoort;
  }
  if (lower.includes("barcelona") || lower.includes("catalunya") || lower.includes("montmelo")) {
    return REAL_CIRCUITS.barcelona;
  }

  // Fallback match by lap distance if distance is within ~3% of official FIA length
  if (totalDist && totalDist > 1000) {
    for (const c of Object.values(REAL_CIRCUITS)) {
      if (Math.abs(c.officialDistance - totalDist) / c.officialDistance < 0.035) {
        return c;
      }
    }
  }

  return null;
}
